const PRECOS_OFICIAIS = {
  essencial: 1,
  pro: 1,
  empresa: 1
};
const items = $input.all();
const results = [];
for (const item of items) {
  const raw = item.json || {};
  const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
  const planoKey = String(body.plano || 'pro').trim().toLowerCase();
  const valorMensal = PRECOS_OFICIAIS[planoKey] || PRECOS_OFICIAIS.pro;
  const empresa = String(body.empresa || 'Cliente AtendeJa').trim();
  const atendente = String(body.atendente || 'Atendente').trim();
  const nicho = String(body.nicho || 'geral').trim();
  const whatsapp = String(body.whatsapp || '').replace(/\D/g, '');
  const cidade = String(body.cidade || '').trim();
  const metodo = 'pix';
  const ts = Date.now();
  const external_reference = 'ATJ-' + ts + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
  const email = String(body.email || '').trim() || ('cliente+' + ts + '@atendeja.com.br');
  const description = 'AtendeJa Plano ' + planoKey.toUpperCase() + ' - ' + empresa;
  results.push({
    json: {
      external_reference,
      pedidoId: external_reference,
      plano: planoKey,
      valorMensal,
      metodo,
      description,
      email,
      empresa,
      atendente,
      nicho,
      whatsapp,
      cidade,
      metadata: {
        pedidoId: external_reference,
        plano: planoKey,
        empresa,
        atendente,
        nicho,
        whatsapp,
        cidade
      }
    }
  });
}
return results;

const secret = 'atendeja-payment-webhook-secret-n8n-2026';
const item = $json;
const m = item.metadata || {};

const email = String(item.payer?.email || m.email || '').toLowerCase().trim();
const plan = String(m.plano || 'pro').toLowerCase().trim();
const amount = Number(item.transaction_amount || 1.00);
const paymentId = String(item.id || item.payment_id || '').trim();
const paidAt = item.date_approved || new Date().toISOString();

const payload = {
  payment_id: paymentId,
  email_google: email,
  plan_code: plan,
  amount_brl: amount,
  status: 'approved',
  payment_method: 'pix',
  paid_at: paidAt
};

const raw = JSON.stringify(payload);
let sigHex = '';

try {
  const c = require('crypto');
  sigHex = c.createHmac('sha256', secret).update(raw).digest('hex');
} catch (_e) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const buf = await crypto.subtle.sign('HMAC', key, enc.encode(raw));
  sigHex = Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

return [{
  json: {
    ...payload,
    signature: 'sha256=' + sigHex
  }
}];

